import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_scale_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void gemm_scale_kernel(const float* x, 
                                  const float* weight, 
                                  const float* bias, 
                                  const float* scale, 
                                  float* out, 
                                  int batch_size, 
                                  int in_features, 
                                  int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_features) {
        int i = idx / out_features; // batch index
        int j = idx % out_features; // output feature index
        float val = 0.0f;
        for(int k = 0; k < in_features; k++){
            val += x[i * in_features + k] * weight[j * in_features + k];
        }
        val += bias[j];
        val *= scale[j];
        out[idx] = val;
    }
}

torch::Tensor gemm_scale_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale
) {
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    TORCH_CHECK(scale.dim() == 1, "scale must be 1D");

    const auto batch_size = x.size(0);
    const auto in_features = x.size(1);
    const auto out_features = weight.size(0);

    auto opts = x.options();
    auto out = torch::empty({batch_size, out_features}, opts);

    const int threads = 256;
    const int blocks = (batch_size * out_features + threads - 1) / threads;

    gemm_scale_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

gemm_scale_cpp_source = r"""
torch::Tensor gemm_scale_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale
);
"""

gemm_scale = load_inline(
    name="gemm_scale",
    cpp_sources=[gemm_scale_cpp_source],
    cuda_sources=[gemm_scale_source],
    functions=["gemm_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses matrix multiplication and scaling in a custom CUDA kernel,
    then applies batch normalization.
    """
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)

    def forward(self, x):
        x = gemm_scale.gemm_scale_cuda(x, self.weight, self.bias, self.scale)
        x = self.bn(x)
        return x
